use crate::domains::kernel_opt::corpus::KernelRule;

pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── K1 — the GOAT lead: a megakernel's text exceeds every instruction
        // cache on the path; the remedy reads the kernel's OWN TEXT AS DATA at
        // launch — one converged warp, one 4-B probe load per 128-B line, the
        // evict_last L2 policy, loads only — so the instruction fetch finds
        // every line in L2. Re-warm EVERY launch; spread the readers, never
        // split the work. ──────────────────────────────────────────────────
        KernelRule {
            rule_id: "launch-time-code-as-data-l2-warm".to_string(),
            gpu_concept: "MECHANISM (instruction-text-as-data L2 warming at launch; category D — dispatch/code-placement): a persistent megakernel whose TEXT exceeds every instruction cache on its path pays an HBM instruction-fetch at first use for every line past the launch prefetch window, EVERY launch — the layer's text (200-320 KB, verbatim kernels/README.md: 'Text size: a layer's 200-320 KB of text is fetched again at every launch, and only about the first 64 KB arrives with the launch (the code prefetch loads the rest into L2)') does not stay in L2 between two launches of its module: 'the layers in between stream more normal-priority bytes than L2 holds (the expert prefetch first of all)' (layer.cu:34-35). THE REMEDY reads the kernel's OWN TEXT AS DATA from the load side at launch, verbatim (layer.cu:33): 'Code prefetch: the kernel's own TEXT made L2-hot from the DATA side at launch.' — 'a plain data load of one word per 128-B line of the kernel's code puts the line in L2; so every launch prefetches the whole text again, the window's lines too' (:35-38). THE FIVE LAWS. (1) LOADS ONLY: the probe values are consumed by nothing — verbatim :42 'Loads only: the arithmetic is untouched.'; the source folds each probe into an XOR sink behind an improbable condition so the loads stay live and the L2 fill is their only effect. (2) THE POLICY IS EVICT_LAST, not normal priority — the PTX cookie verbatim 'createpolicy.fractional.L2::evict_last.b64 pol, 1.0' on 'ld.global.cg.L2::cache_hint' probe loads: normal-priority lines are washed by the inter-layer streams, pinned lines survive ('Evict-last keeps the lines longer than the normal priority, not for good'). (3) RE-WARM EVERY LAUNCH: the fill does not persist across launches (law 2's streams) — the warm pass runs at every launch of the module, window lines included. (4) SPREAD THE READERS, NEVER SPLIT THE WORK: verbatim :38-39 'One warp issues the loads on each of the nine CTAs with blockIdx.x % 16 == 0, every one of them loading every line.' — multi-die GPUs keep a separate L2 copy per die, so each die needs its own full walk; splitting the range across readers leaves the other die's copy cold and the exec misses return. (5) THE TEXT RANGE IS BOUND BY THE HOST AT MODULE LOAD, never scanned in-kernel: verbatim (:49-53) 'Before loading the cubin the host retypes that relocation to R_CUDA_64 (the absolute text address) and writes the kernel's .text size into `bytes`' — the emitted image carries {&kernel, 0} with an R_CUDA_DESCRIPTOR relocation on the entry; 'an unbound range prefetches nothing'. PLACEMENT LAW: the warm routine is `__noinline__` so ptxas places it BEHIND the kernel body — verbatim (:58-61) 'Out of line: ptxas places the routine behind the kernel body, so it adds no text ahead of the phases that follow (text ahead of the MoE phase would push it out of the launch prefetch window).' BUILD LAW: the host's code-prefetch patch edits the cubin's ELF before loading it, so the layer images are built 'with --compress-mode=none ... which needs the uncompressed image' (kernels/README.md:57-58). CAVEATS CARRIED IN-RULE (the verdict's round 1): PORTABILITY — the ELF-relocation retype relies on UNDOCUMENTED toolchain behavior and may break across ptxas/driver versions (the README itself pins the uncompressed image); ANTI-REGIME — the trick presumes instruction fetch is backed by the SAME L2 that data loads fill, verified on Blackwell/GB300 (sm_103a) only and UNKNOWN on Apple GPUs (our own lanes — the Metal microbench port is the lane-intel step, Research 398 §Lane intel 1); SCHEDULE-KEEP — the same README records 'the layer images carry unread constructs because removing them changes ptxas's schedule of the images, not the work, and measured 1-2 % slower per step at TP8 (neutral or faster at TP4)' — code placement is schedule-sensitive; never pair this law with text-shrinking edits without re-measuring. COMPOSE with attention-softmax-state-exchange-once-per-block (gpu_110), which owns the ROLLED-LOOP AVOIDANCE arm of the same icache pressure ('fully unrolled, the code outgrew the instruction cache and ran 5x slower') — shrinking text reduces the window this law re-warms; they compose, never merge. Distinct-from producer-store-evict-last-pins-cross-stream-consumer, which owns evict_last for DATA lifetime (a store side policy pinning a consumer's data across streams) — THIS pins the kernel's own TEXT from the load side at launch; a different resource (instruction lines), a different direction (loads), a different lifetime (one launch interval). REGIME: persistent/megakernel serving lanes where one module's text exceeds the SM icache and the launch interval between uses of the same text is filled with other layers' streams; any device program whose cold instruction fetches are a measured first-use tax. ANTI-REGIME: small kernels (text inside the launch window — nothing to warm); engines where instruction fetch is NOT backed by the data-fill L2 (unverified on non-Blackwell — the port must measure first); toolchains where the ELF patch breaks. BLOG MAGNITUDE (blog-sourced, never in-code): two 100 KB straight-line blocks stitched run 19.5 µs each vs 12.4 µs solo; 20 KB + 100 KB fits and runs at solo speed — root cause icache, explicitly NOT register spills. NotBenchable here (the win is HBM instruction-traffic on GB300-class devices; no validator hosts that — the dial9/136 annotation, not a demotion); the fixture proves warm coverage, loads-only, the split-reader miss, and the unbound no-op. Source: facebookresearch/sgl-muse-mega (MIT) @ f009237dfc56ee130c1637352ff356093a870ecc — sgl_muse_mega/muse_spark/sm103/kernels/layer.cu:33-61 + :63-90 (the CodePrefetch block, quoted above; the probe loop's evict_last asm), kernels/README.md:57-58 + :79-88 + :124 (text size, compress-mode, schedule-keep, the reschedule-slower record). Batch 354 / Plan 364 / Research 398.".to_string(),
            ref_shape: "// naive: the launch relies on the hardware prefetch alone — the\n// first ~64 KB-equivalent of the module's text arrives with the launch;\n// every instruction line past the window fetches from HBM at first use,\n// EVERY launch (the inter-layer streams wash normal-priority lines).\n// Readiness, if tracked at all, is a one-time warmup nobody re-runs.\nconst LINE_BYTES: usize = 128;\nconst WINDOW_LINES: usize = 4;\n\n#[derive(Default)]\nstruct MockL2 {\n    pinned: std::collections::BTreeSet<usize>,\n    normal: std::collections::BTreeSet<usize>,\n}\n\nimpl MockL2 {\n    fn stream_other_layers(&mut self) {\n        self.normal.clear(); // the layers in between streamed\n    }\n    fn touch_exec(&mut self, line: usize, hbm_fetches: &mut usize) {\n        if self.pinned.contains(&line) || self.normal.contains(&line) {\n            self.normal.insert(line);\n        } else {\n            *hbm_fetches += 1; // instruction fetch from HBM at first use\n            self.normal.insert(line);\n        }\n    }\n}\n\nfn launch_naive(lines: usize, l2: &mut MockL2) -> usize {\n    let mut hbm = 0;\n    l2.stream_other_layers();\n    for line in 0..lines {\n        if line >= WINDOW_LINES {\n            l2.touch_exec(line, &mut hbm);\n        }\n    }\n    hbm\n}".to_string(),
            opt_pattern: "// optimized: every launch, each die's converged warp probes ONE\n// 4-B word per 128-B text line at the evict_last L2 policy — loads\n// only, values folded into a discard sink — then the instruction fetch\n// finds every line warm. Readers SPREAD (each die's warp walks ALL\n// lines, staggered), never split: multi-die L2 copies are per die.\n// The text range comes from a host binding; unbound prefetches nothing.\nfn warm_pass_die(text_lines: usize, reader: usize, readers: usize, l2: &mut MockL2, sink: &mut u64) {\n    let mut line = reader;\n    let mut walked = 0;\n    while walked < text_lines {\n        l2.pinned.insert(line); // the L2 fill is the load's only effect\n        *sink = sink.wrapping_add(line as u64); // the probe value's only consumer\n        line = (line + readers) % text_lines;\n        walked += 1;\n    }\n}\n\nfn exec_two_dice(text_lines: usize, dice: &mut [MockL2; 2]) -> usize {\n    let mut hbm = 0;\n    for line in 0..text_lines {\n        if line >= WINDOW_LINES {\n            dice[(line + 1) % 2].touch_exec(line, &mut hbm);\n        }\n    }\n    hbm\n}\n\nfn launch_warmed(lines: usize, dice: &mut [MockL2; 2], readers: usize, bind: Option<(usize, usize)>) -> usize {\n    let mut sink = 0u64;\n    for d in dice.iter_mut() {\n        d.stream_other_layers();\n    }\n    if let Some((_base, bytes)) = bind {\n        let n = bytes / LINE_BYTES;\n        for d in dice.iter_mut() {\n            for r in 0..readers {\n                warm_pass_die(n, r, readers, d, &mut sink); // every die reads every line\n            }\n        }\n    } // unbound range prefetches nothing\n    exec_two_dice(lines, dice)\n}".to_string(),
        },
        // ── K2 — the dry pass: a latency-critical loop runs TWICE — the first
        // pass executes the SAME instruction addresses with effects skipped,
        // on garbage accumulators; the real pass then finds every line in the
        // instruction cache. Rolled (one copy of its text) is load-bearing. ─
        KernelRule {
            rule_id: "dry-pass-icache-warm-before-real".to_string(),
            gpu_concept: "MECHANISM (dry-pass instruction-cache warming; category D — dispatch/code-placement): a latency-critical loop whose first real pass would fetch every instruction line cold runs the loop TWICE — the first pass executes the SAME instruction addresses with its effects (stores, publishes, waits, arrives) skipped, on garbage accumulators, inside a window the schedule already waits through — so the real pass finds every line in the instruction cache. Verbatim (moe.cuh:2479-2482): 'The dry pass: cell 0's g1 epilogue body runs once ahead of it on the emit warp and the non-stager drainer warps (w8-w11), in the tables -> rows window, on the accumulator's garbage, with no waits and no arrives: the same instruction addresses, so every CTA's first drain finds its lines in the instruction cache. The staging it writes is rewritten by the real cell before any emit.' — the dry pass MAY write staging because the real pass rewrites it before anything reads it. Sites: the g1 join/emit warp verbatim (:1536-38) 'the dry pass (the hoisted loop body): cell 0's join / store body once ahead of it, without its effects.'; the drainer half verbatim (:1557) 'the dry pass: ci = -1 runs cell 0's body once more ahead of it, with no waits and no arrives' — the loop counter STARTS at -1 so iteration zero is the dry run of cell 0; the next-layer combine row and the layer-final norm, verbatim (next_layer.cuh:163) 'The row runs twice in one rolled loop (one copy of its text): first DRY (its loads and arithmetic on this CTA's scratch, no exchange, no y store, no publish) between the caller's cluster-barrier arrive and wait, to warm the instruction cache, then for real behind the wait and the row's polls.' and (:710-713) 'first DRY while the row is still landing, to warm the instruction cache, then for real.' THE TWO LAWS. (1) THE LOOP STAYS ROLLED — one copy of its text, verbatim (kernels/README.md:80-82) 'loops that carry no per-element register state stay rolled (`#pragma unroll 1`; the MoE phase's z / SF pushes to the peers at `unroll 4`): the same per-thread sequence of copies, issues and waits, so the arithmetic is bitwise the unrolled loop's, in fewer bytes.' An unrolled dry pass would warm a COPY of the text the real rolled loop never executes (blog-sourced) — the dry pass is only a warm if dry and real execute the same addresses, which for a C-source loop means `#pragma unroll 1` on BOTH passes. (2) THE SHAPE GATE: the loop must carry NO per-element register state across iterations — the dry pass computes on garbage, so any loop whose iteration i+1 consumes iteration i's value cannot dry-pass (its garbage would flow into the real computation). Effects discipline: the dry pass skips waits/arrives/publishes/stores OR writes only staging the real pass rewrites before any read — never an observable effect. COMPOSE with launch-time-code-as-data-l2-warm (this file's K1) — MANDATORY in-rule adjudication BOTH directions: K1 is the COARSE arm (the whole module's text made L2-hot from the data side at launch, per-128-B-line probe loads, host-bound range, multi-die spread); THIS is the FINE arm (one loop's exact instruction sequence executed once, effects-skipped, at the SM icache — no host binding, no policy cookie, per-CTA). K1 warms L2 lines the launch will later fetch; K2 warms the icache lines the FIRST execution will later fetch. They compose (K1 at launch, K2 in the first wait window), never merge — neither subsumes the other's resource or granularity. Distinct-from attention-softmax-state-exchange-once-per-block (gpu_110), which owns the ROLLED-LOOP AVOIDANCE arm of the icache pressure (do not unroll past the icache) — THIS owns the dry-pass WARM arm (run the rolled loop twice, effects skipped); the code-footprint arm of the icache discipline lands HERE (this rule carries the README's rolled-loop law quote + the ~50 KB unroll delta as its shape gate), gpu_110 keeps the kin pointer only — an attention-exchange rule must not become the corpus's retrieval hit for icache queries. REGIME: latency-critical first passes inside an existing wait window (a producer's readiness poll, a barrier arrive->wait gap, a row still landing); hot loops whose cold-fetch tax is measured; loops with no cross-iteration state. ANTI-REGIME: loops already warm (a repeated pass — the first run paid, later runs are free); loops with per-element register state; effects that are NOT idempotent-or-overwritten (a dry store anything reads before the real pass = the tampered fixture's garbage). BLOG MAGNITUDE (blog-sourced, never in-code): 0.5-1 µs per op. NotBenchable here (icache-hit timing on sm_103a; no validator hosts that — the dial9/136 annotation, not a demotion); the fixture proves same-address warming, effects fire once on the real pass only, the unrolled-copy miss, and the garbage-output tamper. Source: facebookresearch/sgl-muse-mega (MIT) @ f009237dfc56ee130c1637352ff356093a870ecc — sgl_muse_mega/muse_spark/sm103/kernels/moe.cuh:2476-2482 + :1535-1538 + :1556-1557, next_layer.cuh:160-166 + :444-446 + :710-713, kernels/README.md:80-88 (the rolled-loop law + the schedule-keep record). Batch 354 / Plan 364 / Research 398.".to_string(),
            ref_shape: "// naive: the latency-critical loop runs ONCE, cold — every step\n// fetches its instruction line at first use inside the latency window\n// the pass is supposed to hide; the effects are correct but the first\n// pass pays the full cold-fetch tax.\nconst STEPS: usize = 12;\n\nstruct LoopMachine {\n    icache: std::collections::BTreeSet<usize>,\n    cold_fetches: usize,\n    stores: Vec<(usize, u64)>,\n}\n\nimpl LoopMachine {\n    fn new() -> Self {\n        Self { icache: std::collections::BTreeSet::new(), cold_fetches: 0, stores: Vec::new() }\n    }\n    fn run_pass(&mut self, steps: &[usize], dry: bool, acc: u64, out: &mut Vec<u64>) {\n        for (i, &step) in steps.iter().enumerate() {\n            if !self.icache.contains(&step) {\n                self.cold_fetches += 1;\n                self.icache.insert(step);\n            }\n            if !dry {\n                self.stores.push((step, acc.wrapping_add(i as u64)));\n                if self.stores.len() == steps.len() {\n                    out.push(acc);\n                }\n            }\n        }\n    }\n}\n\nfn first_pass_cold(steps: &[usize]) -> usize {\n    let mut m = LoopMachine::new();\n    let mut out = Vec::new();\n    m.run_pass(steps, false, 7, &mut out);\n    m.cold_fetches\n}".to_string(),
            opt_pattern: "// optimized: the row runs twice in ONE rolled loop (one copy of\n// its text): first DRY — same addresses, effects skipped, garbage\n// accumulator — then for real. `#pragma unroll 1` semantics are\n// load-bearing: an unrolled dry pass would warm a copy the real\n// rolled loop never runs. Loops carrying per-element register state\n// refuse the dry arm by shape.\nfn warmed_first_pass(steps: &[usize], machine: &mut LoopMachine, acc: u64, out: &mut Vec<u64>) {\n    let stateful = steps.windows(2).all(|w| w[1] == w[0] + 1); // carries a chain\n    assert!(!stateful, \"a stateful loop cannot dry-pass\");\n    machine.run_pass(steps, true, 0, out); // dry: garbage acc, no stores\n    machine.run_pass(steps, false, acc, out); // for real: warm, effects once\n}".to_string(),
        },
        // ── K3 — the speculative expert-weight L2 prefetch: one otherwise-idle
        // warp reads the PREVIOUS step's routing ids, histograms, and
        // fire-and-forget prefetches the most-routed experts' shard packs
        // under the L2 budget — during the attention phase, before the router
        // runs. Budget is POLICY. The router stays authoritative. ──────────
        KernelRule {
            rule_id: "speculative-expert-prefetch-prev-step-routing".to_string(),
            gpu_concept: "MECHANISM (previous-step-routing expert-weight L2 prefetch; category H — MoE dispatch): a batch-1 MoE decode step whose consecutive steps route alike leaves the post-attention aux warp IDLE while the MoE phase's weight streams run cold — the remedy spends the idle warp on a fire-and-forget L2 prefetch of the weight packs this step will most likely need, under the attention phase, before the router runs. Verbatim (moe.cuh:2832-2837): 'The expert-weight L2 prefetch: one warp per CTA (the post-attention aux warp, otherwise idle) reads this layer's routing ids from the PREVIOUS step (the binding's last top-k, read once with acquire; nothing of the predecessor grid), histograms the experts and L2-prefetches the shard packs (W1, W2 and their scale factors) of the most-routed experts that fit the L2 budget, spread over every CTA of the launch, under the attention phase, long before this step's router runs. Consecutive steps route alike, so the MoE phase's g1 / g2 weight streams mostly hit L2.' THE FOUR LAWS. (1) THE SIGNAL IS THE PREVIOUS STEP'S OWN ROUTING — the binding's last top-k, read ONCE with acquire, nothing of the predecessor grid: no model of routing, no learned predictor, just last step's answer as this step's schedule hint. (2) FIRE-AND-FORGET: GPU-L2 with NO explicit cache structure — no admission list, no eviction victim policy, no write-back bookkeeping; a wrong guess costs bandwidth only, while the GPU is idle anyway (blog-sourced: ~0.2 ms of a 5.3 ms step). (3) THE BUDGET IS POLICY, NEVER A CONSTANT — verbatim (:2848-2855) 'as many of the most-routed experts as fit a 48 MiB L2 budget (14 at the TP8 NVFP4 shard, 3.375 MiB an expert; the bf16 variant's at every world), or 4 (cfg::kWorld.prefetch_wide off: the TP4 NVFP4 shard, 6.75 MiB an expert, where the wide budget's traffic costs the post-attention window more than it saves the MoE phase).' — the wide budget is enabled per world by measuring whether its traffic taxes the post-attention window more than it saves the MoE; the narrow default is the honest posture under that tax. (4) THE ROUTER STAYS AUTHORITATIVE: the prefetch schedules BYTES, never the selection — the step's experts are whatever this step's router answers; the prefetch only decides which answers are already warm. Plus at router-landing (blog-sourced): each block prefetches its first expert tile beside reading the table, and experts already in L2 go FIRST in the tile list (residency-ordered demand). MANDATORY IN-RULE ADJUDICATION SET (the consecutive-step-reuse premise family — all four verified on disk at landing HEAD): expert-major-tile-order-token-tile-cache-resident (gpu_39) owns the tile ENUMERATION axis (grid-axis order vs THIS rule's L2-RESIDENCY priority — different axis); cold-large-prefill-whole-layer-lookahead-over-partial-cache (gpu_31) owns the SSD-TIER lookahead with a PROMPT-FREQUENCY signal (different TIER — host/SSD reads, not GPU-L2 — and different SIGNAL); expert-cache-write-path-regime-gated (gpu_79) + decayed-frequency-eviction-recency-tiebreak-route-protection (B94) + rust_perf's host-resident two-list expert cache (entries_35's slru-probation family) all maintain an explicit CACHE STRUCTURE (admission, eviction, recency) — THIS rule deliberately has none (law 2); moe-readiness-queue-no-grid-barrier-producer-scans-before-retire (gpu_87) is the MoE-dispatch kin (readiness/queue discipline around the same dispatch path). PUBLISHED PRIOR ART (recorded, the verdict's round 1 narrowing): the host-to-HBM tier of this class IS published — Eliseev & Mazur arXiv:2312.17238 (Mixtral offloading, LRU expert cache + speculative expert loading), MoE-Infinity arXiv:2401.14361 (activation-aware expert prefetch), Pre-gated MoE, ProMoE — so the claim is NARROWED to what that tier does not cover: (a) GPU-L2 with no cache structure (fire-and-forget), (b) an idle warp inside the SAME launch during attention, (c) budget-as-policy keyed on the post-attention window's measured cost, (d) the residency-ordered tile list. C+ on the narrowed claim. REGIME: batch-1 MoE decode with per-step top-k routing where consecutive steps correlate; an idle aux warp in the same launch; L2 large enough to hold several experts' packs. ANTI-REGIME: batched serving (the aux warp is not idle; routing decorrelates across a batch); engines where prefetch traffic taxes a busy window (law 3's narrow posture); tiers that already maintain a cache structure (use gpu_79/B94 instead). NotBenchable here (MoE weight-stream L2 hit rates on GB300 TP8; no validator hosts that — the dial9/136 annotation, not a demotion); the fixture proves most-routed-under-budget selection, the never-prefetch-unrouted gate, budget-as-policy (14 vs 4), residency-first ordering, router authority, and the already-resident no-op. Source: facebookresearch/sgl-muse-mega (MIT) @ f009237dfc56ee130c1637352ff356093a870ecc — sgl_muse_mega/muse_spark/sm103/kernels/moe.cuh:2832-2855 (the mk::expert_prefetch module head + the budget constant block, quoted above; kPrefetchBudget = 50331648). Batch 354 / Plan 364 / Research 398.".to_string(),
            ref_shape: "// naive: the MoE phase streams every selected expert's weight pack\n// cold — the post-attention aux warp sits idle while the g1/g2 weight\n// streams run from HBM, every step, even though consecutive steps\n// route alike.\nconst EXPERTS: usize = 32;\nconst PACK_UNITS: usize = 34;\n\nfn moe_phase_fetch_cold(selected: &[usize]) -> usize {\n    // every pack streams; the idle warp does nothing.\n    selected.len() * PACK_UNITS\n}\n\nfn unused() {\n    let _ = EXPERTS;\n}".to_string(),
            opt_pattern: "// optimized: one idle warp per CTA histograms the PREVIOUS step's\n// routing ids and fire-and-forget prefetches the most-routed experts'\n// packs until the POLICY budget is full (ties to the lower id, never\n// unrouted experts) — during the attention phase, before the router\n// runs. L2-resident experts go FIRST in the tile list; the router's\n// answer is still the selection.\nstruct ExpertPrefetcher {\n    budget_units: usize,\n    l2: std::collections::BTreeSet<usize>,\n    bandwidth_spent: usize,\n}\n\nimpl ExpertPrefetcher {\n    fn prefetch_prev_routing(&mut self, prev_routing: &[u32]) -> Vec<usize> {\n        let mut hist = [0usize; EXPERTS];\n        for &e in prev_routing {\n            hist[e as usize] += 1;\n        }\n        let mut order: Vec<usize> = (0..EXPERTS).collect();\n        order.sort_by_key(|&e| (std::cmp::Reverse(hist[e]), e));\n        let mut picked = Vec::new();\n        let mut used = 0;\n        for &e in &order {\n            if used + PACK_UNITS > self.budget_units {\n                break;\n            }\n            if hist[e] == 0 {\n                break; // never prefetch unrouted experts\n            }\n            if !self.l2.contains(&e) {\n                self.l2.insert(e);\n                self.bandwidth_spent += PACK_UNITS;\n            }\n            picked.push(e);\n            used += PACK_UNITS;\n        }\n        picked\n    }\n    fn moe_phase_fetch(&self, selected: &[usize]) -> usize {\n        selected.iter().map(|&e| if self.l2.contains(&e) { 0 } else { PACK_UNITS }).sum()\n    }\n    fn tile_order(&self, selected: &[usize]) -> Vec<usize> {\n        let mut v = selected.to_vec();\n        v.sort_by_key(|&e| !self.l2.contains(&e)); // resident first, stable\n        v\n    }\n}".to_string(),
        },
    ]
}
